import { Component, input } from '@angular/core';
import { NzTooltipDirective } from 'ng-zorro-antd/tooltip';

/** 1 ô trong dải theo dõi. tooltip do bên gọi cấp (i18n-sạch). */
export interface HrmTrackerItem {
  tone: 'success' | 'warning' | 'error' | 'info' | 'neutral';
  tooltip?: string;
}

/** hrm-tracker — dải ô vuông trạng thái theo trình tự (mỗi ô = 1 ngày/1 ca/1 lần chạy):
 *  chấm công tháng của nhân viên, chuỗi ngày đúng hạn của quy trình. Màu theo tông semantic
 *  token → tự bám Light/Dark. Rê chuột từng ô để xem chi tiết (tooltip). */
@Component({
  selector: 'hrm-tracker',
  imports: [NzTooltipDirective],
  template: `
    @for (it of items(); track $index) {
      <span class="tk-cell" [attr.data-tone]="it.tone"
        nz-tooltip [nzTooltipTitle]="it.tooltip || null"></span>
    }
  `,
  host: {
    class: 'hrm-tracker',
    '[style.--_w]': "cellW() + 'px'",
    '[style.--_h]': "cellH() + 'px'",
    '[style.--_gap]': "gap() + 'px'",
  },
  styles: [`
:host { display: inline-flex; align-items: center; gap: var(--_gap, 3px); max-width: 100%; flex-wrap: wrap; }
.tk-cell {
  flex: none; width: var(--_w, 10px); height: var(--_h, 24px);
  border-radius: var(--radius-xs, 2px);
  transition: opacity var(--duration-fast, .15s) var(--ease-out, ease);
}
.tk-cell:hover { opacity: .75; }
.tk-cell[data-tone='success'] { background: var(--success-base); }
.tk-cell[data-tone='warning'] { background: var(--warning-base); }
.tk-cell[data-tone='error']   { background: var(--error-base); }
.tk-cell[data-tone='info']    { background: var(--info-base); }
.tk-cell[data-tone='neutral'] { background: var(--neutral-300, var(--border-sub)); }
  `],
})
export class HrmTracker {
  readonly items = input<HrmTrackerItem[]>([]);
  /** Kích thước ô + khoảng cách (px). */
  readonly cellW = input(10);
  readonly cellH = input(24);
  readonly gap = input(3);
}
