import { Component, inject } from '@angular/core';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { HrmTracker, HrmTrackerItem } from 'hrm-ui';
import { SgDoc } from '../../../doc/sg-doc';
import { SgUse, SgDo, SgDont, SgExample, SgRow } from '../../../doc/sg-blocks';

/** Doc page · Tracker (Chart) — dải ô trạng thái theo trình tự: chấm công / chuỗi đúng hạn. Song ngữ qua i18n docs.tracker.*. */
@Component({
  selector: 'sg-doc-tracker',
  imports: [TranslateModule, HrmTracker, SgDoc, SgUse, SgDo, SgDont, SgExample, SgRow],
  template: `
    <sg-doc category="Chart" [title]="'docs.tracker.title' | translate" [desc]="'docs.tracker.desc' | translate">

      <div sgOverview>
        <sg-row>
          <hrm-tracker [items]="month" />
        </sg-row>
      </div>

      <div sgUsage>
        <sg-use
          [purpose]="'docs.tracker.purpose' | translate"
          [when]="when"
          [behavior]="'docs.tracker.behavior' | translate"
          [avoid]="'docs.tracker.avoid' | translate" />
      </div>

      <div sgBest>
        <sg-do>{{ 'docs.tracker.do1' | translate }}</sg-do>
        <sg-do>{{ 'docs.tracker.do2' | translate }}</sg-do>
        <sg-dont>{{ 'docs.tracker.dont1' | translate }}</sg-dont>
      </div>

      <div sgExamples>
        <sg-example [title]="'docs.tracker.exMonthT' | translate"
          [desc]="'docs.tracker.exMonthD' | translate">
          <sg-row>
            <hrm-tracker [items]="month" />
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.tracker.exTeamT' | translate"
          [desc]="'docs.tracker.exTeamD' | translate">
          <sg-row>
            <div class="col">
              @for (r of teamRows; track r.name) {
                <div class="trow">
                  <span class="tname">{{ r.name }}</span>
                  <hrm-tracker [items]="r.items" [cellW]="9" [cellH]="18" />
                </div>
              }
            </div>
          </sg-row>
        </sg-example>

        <sg-example [title]="'docs.tracker.exSizeT' | translate"
          [desc]="'docs.tracker.exSizeD' | translate">
          <sg-row [label]="'docs.tracker.rowSize' | translate">
            <div class="col">
              <hrm-tracker [items]="month.slice(0, 14)" [cellW]="14" [cellH]="32" [gap]="4" />
              <hrm-tracker [items]="month.slice(0, 14)" />
              <hrm-tracker [items]="month.slice(0, 14)" [cellW]="6" [cellH]="12" [gap]="2" />
            </div>
          </sg-row>
        </sg-example>
      </div>

    </sg-doc>
  `,
  styles: [`
    .col { display: flex; flex-direction: column; gap: 12px; align-items: flex-start; }
    .trow { display: flex; align-items: center; gap: 12px; }
    .tname { width: 120px; font-size: var(--fs-13); color: var(--text-body); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  `],
})
export class SgDocTracker {
  protected readonly month: HrmTrackerItem[] = this.buildMonth(0);
  protected readonly teamRows = [
    { name: 'Nguyễn Văn An', items: this.buildMonth(1) },
    { name: 'Trần Thu Hà', items: this.buildMonth(2) },
    { name: 'Lê Minh Quân', items: this.buildMonth(3) },
  ];
  protected readonly when = [
    'docs.tracker.when1',
    'docs.tracker.when2',
    'docs.tracker.when3',
  ];

  /** Sinh 30 ngày mẫu, seed đổi nhịp giữa các dòng. */
  private buildMonth(seed: number): HrmTrackerItem[] {
    const t = inject(TranslateService);
    const weekend = t.instant('docs.tracker.tipWeekend');
    const present = t.instant('docs.tracker.tipPresent');
    const late = t.instant('docs.tracker.tipLate');
    const absent = t.instant('docs.tracker.tipAbsent');
    const out: HrmTrackerItem[] = [];
    for (let d = 1; d <= 30; d++) {
      const wd = (d + seed) % 7;
      if (wd === 0 || wd === 6) { out.push({ tone: 'neutral', tooltip: `${String(d).padStart(2, '0')}/06 — ${weekend}` }); continue; }
      const r = (d * 7 + seed * 13) % 10;
      const tone = r < 7 ? 'success' : r < 9 ? 'warning' : 'error';
      const label = tone === 'success' ? present : tone === 'warning' ? late : absent;
      out.push({ tone, tooltip: `${String(d).padStart(2, '0')}/06 — ${label}` });
    }
    return out;
  }
}
